select table_name from information_schema.tables where table_schema='public' and table_name='material_usage_requests';
select column_name,data_type,is_nullable from information_schema.columns where table_schema='public' and table_name='material_usage_requests' order by ordinal_position;
select column_name,is_nullable from information_schema.columns where table_schema='public' and table_name='material_contract_allocations' and column_name='usage_request_id';
select conname,pg_get_constraintdef(oid) from pg_constraint where conrelid in ('public.material_usage_requests'::regclass,'public.material_contract_allocations'::regclass) order by conname;
select policyname,cmd,roles,qual,with_check from pg_policies where schemaname='public' and tablename='material_usage_requests';
select p.proname,p.prosecdef,has_function_privilege('authenticated',p.oid,'EXECUTE') authenticated_execute from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('get_material_usage_requests','create_material_usage_request','allocate_material_usage_request','update_material_usage_request_quantity') order by p.proname;
select count(*) legacy_allocation_count,count(*) filter(where usage_request_id is null) legacy_without_request_count from public.material_contract_allocations;
select r.id,r.quantity_tons,coalesce(sum(a.quantity_tons) filter(where a.status in ('planned','confirmed')),0) allocated_tons,greatest(r.quantity_tons-coalesce(sum(a.quantity_tons) filter(where a.status in ('planned','confirmed')),0),0) unallocated_tons from public.material_usage_requests r left join public.material_contract_allocations a on a.usage_request_id=r.id group by r.id order by r.created_at desc;
select metadata->>'contract_id' contract_id,metadata->>'before_quantity_ton' before_quantity,metadata->>'increase_quantity_ton' increase_quantity,metadata->>'after_quantity_ton' after_quantity,description reason,created_at from public.activity_logs where action_type='material_contract_quantity_increased' order by created_at desc;
